{
  "application": "report-generation",
  "case_id": "case-uk-fuel-prices-trend-analysis-en",
  "language": "en",
  "report": {
    "type": "trend-analysis",
    "audience": "government policy analysts and energy economists",
    "tone": "analytical, data-forward, professional"
  },
  "brief": {
    "title": "UK Retail Fuel Price Trend Analysis — February 2026",
    "one_liner": "A comprehensive analysis of retail fuel pricing patterns across UK forecourts, examining price distributions by fuel type and temporal update behaviour based on government-mandated open data.",
    "goal": "Provide policy analysts and energy researchers with a clear understanding of current UK fuel price levels by fuel type, the distribution and spread of prices across stations, and how frequently retailers update their reported prices — enabling evidence-based assessment of market competitiveness and pricing transparency."
  },
  "required_sections": [
    {
      "section_id": "overview",
      "title": "Dataset Overview & Coverage Summary",
      "objective": "Summarise the scope of the data: total records, number of unique stations (node_ids), fuel types present, and the date range covered. Provide context on data completeness."
    },
    {
      "section_id": "price-by-fuel-type",
      "title": "Price Distribution by Fuel Type",
      "objective": "Analyse the distribution of prices (mean, median, min, max, standard deviation) for each fuel type. Identify which fuel types are most and least expensive and how much variation exists across stations."
    },
    {
      "section_id": "price-spread-analysis",
      "title": "Price Spread & Market Competitiveness",
      "objective": "Examine the range (max minus min) and interquartile range of prices within each fuel type to assess how competitive the market is. Highlight whether consumers face significant price disparities."
    },
    {
      "section_id": "update-freshness",
      "title": "Retailer Reporting Freshness Analysis",
      "objective": "Analyse the lag between source_updated_at and recorded_at timestamps to assess how promptly retailers update their prices. Identify patterns in update frequency and any stations with stale data."
    },
    {
      "section_id": "station-coverage",
      "title": "Station Coverage & Fuel Type Availability",
      "objective": "Examine how many fuel types each station reports, identify which fuel types have the broadest and narrowest station coverage, and flag any data gaps."
    },
    {
      "section_id": "key-findings",
      "title": "Key Findings & Policy Implications",
      "objective": "Synthesise the main insights into actionable findings relevant to fuel pricing policy, consumer protection, and market transparency."
    }
  ],
  "kpis": [
    {
      "name": "Average Price per Litre (by fuel type)",
      "description": "Mean price in pence per litre for each fuel type across all stations, indicating the typical cost consumers face."
    },
    {
      "name": "Price Spread (Max − Min)",
      "description": "The difference between the highest and lowest reported price for each fuel type, measuring market-wide price disparity."
    },
    {
      "name": "Interquartile Range (IQR)",
      "description": "The range between the 25th and 75th percentile prices per fuel type, indicating the typical price band most consumers encounter."
    },
    {
      "name": "Median Update Lag (hours)",
      "description": "The median time difference between source_updated_at and recorded_at, measuring how fresh the reported prices are."
    },
    {
      "name": "Unique Station Count",
      "description": "Total number of distinct forecourts (node_ids) in the dataset, indicating market coverage."
    }
  ],
  "analysis_dimensions": [
    "fuel_type",
    "price_pence",
    "source_updated_at",
    "recorded_at",
    "node_id"
  ]
}

