function populateOverview(data) {
  const kpis = [
    { label: 'Total Records', value: data.overview.total_records.toLocaleString(), unit: '' },
    { label: 'Unique Forecourts', value: data.overview.unique_stations.toLocaleString(), unit: '' },
    { label: 'Fuel Types', value: data.overview.fuel_types.length, unit: '' },
    { label: 'Date Range', value: '68 days', unit: data.overview.date_min + ' – ' + data.overview.date_max },
    { label: 'Data Quality Issues', value: data.overview.outlier_records, unit: 'outlier records (0.25%)' }
  ];
  const grid = document.getElementById('overview-kpis');
  kpis.forEach(k => {
    const card = document.createElement('div');
    card.className = 'kpi-card';
    card.innerHTML = `<div class="kpi-label">${k.label}</div><div class="kpi-value">${k.value}</div><div class="kpi-unit">${k.unit}</div>`;
