function makeBoxPlot(data) {
  const fuelOrder = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO'];
  const names = {E10:'E10 Unleaded', B7_STANDARD:'B7 Diesel', E5:'E5 Super', B7_PREMIUM:'B7 Premium', B10:'B10 Diesel', HVO:'HVO'};
  const colors = {E10:'#2563eb', B7_STANDARD:'#dc2626', E5:'#3b82f6', B7_PREMIUM:'#b91c1c', B10:'#7c3aed', HVO:'#059669'};

  const traces = [];
  fuelOrder.forEach(ft => {
    if (!data.box_data[ft]) return;
    const d = data.box_data[ft];
    traces.push({
      type: 'box',
      name: names[ft],
      y: [d.min, d.q1, d.median, d.q3, d.max],
      marker: { color: colors[ft] },
      line: { color: colors[ft], width: 2 },
      boxmean: true,
      boxpoints: false,
      hovertemplate: `<b>${names[ft]}</b><br>Min: %{customdata[0]} ppl<br>Q1: %{customdata[1]} ppl<br>Median: %{customdata[2]} ppl<br>Q3: %{customdata[3]} ppl<br>Max: %{customdata[4]} ppl<br>Mean: %{customdata[5]} ppl<extra></extra>`,
      customdata: [[d.min, d.q1, d.median, d.q3, d.max, d.mean]]
    });
  });

  Plotly.newPlot('chart-boxplot', traces, {
    title: { text: 'Price Distribution by Fuel Type (Box Plot)', font: { size: 15, color: '#1c1917' } },
    yaxis: { title: 'Price (pence per litre)', gridcolor: '#f0f0f0', zeroline: false },
    xaxis: { title: 'Fuel Type' },
    margin: { t: 50, r: 30, b: 60, l: 70 },
    plot_bgcolor: '#fafaf9',
    paper_bgcolor: '#ffffff',
    showlegend: false
  }, { responsive: true });
}

function makeViolinPlot(data) {
