function makeIQRChart(data) {
  const fuelOrder = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO'];
  const names = {E10:'E10', B7_STANDARD:'B7 Diesel', E5:'E5', B7_PREMIUM:'B7 Prem.', B10:'B10', HVO:'HVO'};
  const colors = {E10:'#2563eb', B7_STANDARD:'#dc2626', E5:'#3b82f6', B7_PREMIUM:'#b91c1c', B10:'#7c3aed', HVO:'#059669'};

  const spreads = [], iqrs = [], labels = [], barColors = [];
  fuelOrder.forEach(ft => {
    if (!data.box_data[ft]) return;
    spreads.push(data.box_data[ft].spread);
    iqrs.push(data.box_data[ft].iqr);
    labels.push(names[ft]);
    barColors.push(colors[ft]);
  });

  const trace1 = {
    type: 'bar',
    name: 'Max−Min Spread',
    x: labels,
    y: spreads,
    marker: { color: barColors.map(c => c + '44'), line: { color: barColors, width: 1.5 } },
    hovertemplate: '<b>%{x}</b><br>Max−Min Spread: %{y:.1f} ppl<extra></extra>'
  };
  const trace2 = {
    type: 'bar',
    name: 'Interquartile Range (IQR)',
    x: labels,
    y: iqrs,
    marker: { color: barColors, line: { width: 0 } },
    hovertemplate: '<b>%{x}</b><br>IQR: %{y:.1f} ppl<extra></extra>'
  };

  Plotly.newPlot('chart-iqr', [trace1, trace2], {
    title: { text: 'Price Spread vs Interquartile Range by Fuel Type', font: { size: 15, color: '#1c1917' } },
    yaxis: { title: 'Pence per Litre', gridcolor: '#f0f0f0' },
    barmode: 'group',
    margin: { t: 50, r: 30, b: 60, l: 70 },
    plot_bgcolor: '#fafaf9',
    paper_bgcolor: '#ffffff',
    legend: { orientation: 'h', y: 1.12 }
  }, { responsive: true });
}

function makeLagHistogram(data) {
  Plotly.newPlot('chart-lag-histogram', [{
    type: 'histogram',
    x: data.lag_histogram.counts,
    xbins: {
      start: data.lag_histogram.bins[0],
      end: data.lag_histogram.bins[data.lag_histogram.bins.length - 1],
      size: data.lag_histogram.bins[1] - data.lag_histogram.bins[0]
    },
    marker: { color: '#2563eb', line: { color: '#1d4ed8', width: 0.5 } },
    hovertemplate: 'Lag %{x:.0f}–%{customdata:.0f}h: %{y} records<extra></extra>',
    customdata: data.lag_histogram.bins.slice(1)
  }], {
    title: { text: 'Distribution of Update Lag (0–72 hours, clean data)', font: { size: 15, color: '#1c1917' } },
    xaxis: { title: 'Update Lag (hours)', gridcolor: '#f0f0f0' },
    yaxis: { title: 'Number of Records', gridcolor: '#f0f0f0' },
    margin: { t: 50, r: 30, b: 60, l: 70 },
    plot_bgcolor: '#fafaf9',
    paper_bgcolor: '#ffffff',
    bargap: 0.05
  }, { responsive: true });
}

function makeLagByFuelChart(data) {
  const fuelOrder = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO'];
  const names = {E10:'E10', B7_STANDARD:'B7 Diesel', E5:'E5', B7_PREMIUM:'B7 Prem.', B10:'B10', HVO:'HVO'};
  const colors = {E10:'#2563eb', B7_STANDARD:'#dc2626', E5:'#3b82f6', B7_PREMIUM:'#b91c1c', B10:'#7c3aed', HVO:'#059669'};

  const labels = [], medians = [], p75s = [], p90s = [], barColors = [];
  fuelOrder.forEach(ft => {
    if (!data.lag_data[ft]) return;
    labels.push(names[ft]);
