    p75s.push(data.lag_data[ft].p75);
    p90s.push(data.lag_data[ft].p90);
    barColors.push(colors[ft]);
  });

  const trace1 = {
    type: 'bar', name: 'Median', x: labels, y: medians,
    marker: { color: barColors.map(c => c + 'CC') },
    hovertemplate: '<b>%{x}</b><br>Median: %{y:.2f}h<extra></extra>'
