    hovertemplate: '<b>%{x}</b><br>P90: %{y:.2f}h<extra></extra>'
  };

  Plotly.newPlot('chart-lag-by-fuel', [trace1, trace2, trace3], {
    title: { text: 'Update Lag Percentiles by Fuel Type (hours)', font: { size: 15, color: '#1c1917' } },
    yaxis: { title: 'Hours', gridcolor: '#f0f0f0', zeroline: true },
