function makeFuelCompositionChart(data) {
  const fuelOrder = ['B7_STANDARD', 'E10', 'E5', 'B7_PREMIUM', 'HVO', 'B10'];
  const names = {E10:'E10 Unleaded', B7_STANDARD:'B7 Diesel', E5:'E5 Super', B7_PREMIUM:'B7 Premium', B10:'B10 Diesel', HVO:'HVO'};
  const colors = {E10:'#2563eb', B7_STANDARD:'#dc2626', E5:'#3b82f6', B7_PREMIUM:'#b91c1c', B10:'#7c3aed', HVO:'#059669'};

  const labels = [], values = [], barColors = [];
  fuelOrder.forEach(ft => {
    if (!data.price_summary.find(p => p.fuel_type === ft)) return;
    const p = data.price_summary.find(ps => ps.fuel_type === ft);
    labels.push(names[ft]);
    values.push(data.box_data[ft].count);
    barColors.push(colors[ft]);
  });

  Plotly.newPlot('chart-fuel-composition', [{
    type: 'pie',
    labels: labels,
    values: values,
    marker: { colors: barColors },
    textinfo: 'label+percent',
    textposition: 'outside',
    hovertemplate: '<b>%{label}</b><br>%{value} records (%{percent})<extra></extra>'
  }], {
    margin: { t: 20, r: 30, b: 20, l: 30 },
    paper_bgcolor: '#ffffff',
    showlegend: false
  }, { responsive: true });
}

function populatePriceTable(data) {
  const tbody = document.getElementById('price-stats-body');
  const fuelOrder = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO'];
  const names = {E10:'E10 Std Unleaded', B7_STANDARD:'B7 Std Diesel', E5:'E5 Super Unleaded', B7_PREMIUM:'B7 Premium Diesel', B10:'B10 Diesel', HVO:'HVO'};
  const tags = {E10:'tag-petrol', B7_STANDARD:'tag-diesel', E5:'tag-petrol', B7_PREMIUM:'tag-premium', B10:'tag-green', HVO:'tag-green'};

  fuelOrder.forEach(ft => {
    const p = data.price_summary.find(ps => ps.fuel_type === ft);
    if (!p) return;
    const row = document.createElement('tr');
    row.innerHTML = `
      <td><span class="tag ${tags[ft]}">${names[ft]}</span></td>
      <td class="num">${p.records || data.box_data[ft].count}</td>
      <td class="num"><strong>${p.mean}</strong></td>
      <td class="num">${p.median}</td>
      <td class="num">${p.min}</td>
      <td class="num">${p.max}</td>
      <td class="num">${p.std}</td>
      <td class="num">${p.iqr}</td>
      <td class="num">${p.spread}</td>
    `;
    tbody.appendChild(row);
  });
}

function populateLagKPIs(data) {
  const kpis = [
    { label: 'Median Update Lag', value: '~3 min', unit: 'near-real-time for most' },
    { label: 'Records Under 1 Hour', value: data.overall_lag.pct_under_1h.toFixed(1) + '%', unit: 'automated reporting' },
    { label: 'Records Over 7 Days Stale', value: data.overall_lag.pct_over_7d.toFixed(1) + '%', unit: 'compliance concern' },
    { label: 'Negative Lag Records', value: data.overall_lag.negative_lag_pct.toFixed(1) + '%', unit: 'timestamp ordering issues' },
    { label: 'Max Lag Observed', value: data.overall_lag.max_lag_days.toFixed(1) + ' days', unit: 'extreme staleness case' }
  ];
  const grid = document.getElementById('lag-kpis');
  kpis.forEach(k => {
    const card = document.createElement('div');
    card.className = 'kpi-card';
    card.innerHTML = `<div class="kpi-label">${k.label}</div><div class="kpi-value">${k.value}</div><div class="kpi-unit">${k.unit}</div>`;
    grid.appendChild(card);
  });
}

// Main init
async function init() {
  let data;
  if (typeof DATA === 'object' && DATA.overview) {
    data = DATA;
  } else {
    data = await loadData();
  }

  populateOverview(data);
  populatePriceTable(data);
  populateLagKPIs(data);

  makeBoxPlot(data);
  makeViolinPlot(data);
  makeIQRChart(data);
  makeLagHistogram(data);
  makeLagByFuelChart(data);
  makeStationCoverageChart(data);
  makeStationFuelCountChart(data);
  makeFuelCompositionChart(data);
}

document.addEventListener('DOMContentLoaded', init);
</script>
